-- SEED DATA - 18. BLOGS
INSERT INTO blogs (author_id, title, content, status) VALUES
(3, N'5 lỗi kỹ thuật phổ biến khi tập Squat', N'Squat là bài tập nền tảng nhưng cũng là bài dễ chấn thương nhất nếu sai kỹ thuật. Dưới đây là 5 lỗi phổ biến nhất...', N'PUBLISHED'),
(4, N'Chế độ ăn giảm mỡ hiệu quả: Không cần nhịn ăn', N'Nhiều người nghĩ giảm mỡ đồng nghĩa với nhịn ăn. Sự thật là bạn cần ăn đúng cách, không phải ăn ít...', N'PUBLISHED'),
(1, N'GymPro khai trương cơ sở mới tại Quận 7', N'Chúng tôi vui mừng thông báo cơ sở GymPro thứ 3 tại 123 Nguyễn Lương Bằng sẽ chính thức hoạt động từ 01/07/2025...', N'PUBLISHED'),
(5, N'Powerlifting cho người mới bắt đầu', N'Bài viết đang được soạn thảo...', N'DRAFT'),
(6, N'Phục hồi chấn thương vai: Những điều cần biết', N'Chấn thương vai là một trong những vấn đề phổ biến nhất ở người tập gym lâu năm. Bài viết chia sẻ các bước phục hồi an toàn...', N'PUBLISHED'),
(7, N'CrossFit có phù hợp với người mới tập không?', N'CrossFit nổi tiếng với cường độ cao và đa dạng bài tập. Tuy nhiên người mới cần lưu ý một số điều trước khi bắt đầu...', N'PUBLISHED'),
(8, N'Dinh dưỡng trước và sau khi tập: Ăn gì là đủ?', N'Thời điểm ăn cũng quan trọng như những gì bạn ăn. Bài viết phân tích chi tiết bữa ăn trước và sau buổi tập...', N'PUBLISHED'),
(9, N'Calisthenics: Tập thể hình không cần tạ', N'Bạn có thể xây dựng cơ bắp ấn tượng chỉ với trọng lượng cơ thể. Đây là lộ trình calisthenics cơ bản...', N'PUBLISHED'),
(10, N'Boxing và Cardio Kickboxing: Đốt calo cực nhanh', N'Một giờ boxing có thể đốt tới 600-800 calo. Bài viết giới thiệu các bài tập cơ bản cho người mới...', N'PUBLISHED'),
(11, N'Pilates cho phụ nữ sau sinh: Bắt đầu từ đâu?', N'Sau sinh, cơ thể cần thời gian phục hồi trước khi quay lại tập luyện cường độ cao. Pilates là lựa chọn an toàn...', N'PUBLISHED'),
(12, N'Bí quyết tăng cơ nhanh cho người gầy', N'Tăng cân và tăng cơ với người có thể trạng gầy thường khó hơn. Bài viết chia sẻ chế độ ăn và tập phù hợp...', N'PUBLISHED'),
(13, N'Tập gym cho người trung niên: An toàn và hiệu quả', N'Người trên 40 tuổi cần một lộ trình tập khác biệt để vừa an toàn vừa đạt hiệu quả sức khỏe lâu dài...', N'PUBLISHED'),
(2, N'Lịch nghỉ Tết 2026 của GymPro', N'GymPro xin thông báo lịch nghỉ Tết Nguyên Đán 2026 và lịch hoạt động trở lại sau Tết để hội viên sắp xếp lịch tập...', N'PUBLISHED'),
(3, N'Deadlift đúng cách: Hướng dẫn từng bước cho người mới', N'Deadlift là một trong những bài tập compound hiệu quả nhất nhưng cũng dễ gây chấn thương lưng nếu sai kỹ thuật...', N'PUBLISHED'),
(4, N'Yoga buổi sáng: 10 phút mỗi ngày thay đổi cơ thể bạn', N'Chỉ cần 10 phút yoga mỗi sáng có thể cải thiện đáng kể sự linh hoạt và tinh thần cho cả ngày làm việc...', N'PUBLISHED'),
(1, N'GymPro ra mắt gói VIP mới với thực đơn cá nhân hóa', N'Từ tháng 7, gói VIP của GymPro sẽ có thêm tùy chọn thực đơn cá nhân hóa theo mục tiêu riêng của từng hội viên...', N'PUBLISHED'),
(7, N'HIIT 20 phút: Bài tập cho người không có nhiều thời gian', N'Không có thời gian không còn là lý do để bỏ tập. Bài viết giới thiệu bài HIIT chỉ 20 phút nhưng hiệu quả cao...', N'PUBLISHED'),
(5, N'So sánh Squat, Deadlift và Leg Press: Nên chọn bài nào?', N'Cả ba bài tập đều tác động vào nhóm cơ chân nhưng theo cách khác nhau. Bài viết phân tích ưu nhược điểm từng bài...', N'DRAFT');
GO

